package com.renthouse.operation;import com.renthouse.auth.*;import com.renthouse.common.api.*;import com.renthouse.common.id.SnowflakeIdGenerator;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/landlord/properties")public class PropertyController{private final JdbcTemplate j;private final SnowflakeIdGenerator ids;public PropertyController(JdbcTemplate j,SnowflakeIdGenerator ids){this.j=j;this.ids=ids;}@PostMapping("/buildings")ApiResponse<String>building(@RequestBody @Valid Building r){CurrentUser.requireRole(UserRole.LANDLORD);long id=ids.nextId();j.update("INSERT INTO property_building(id,landlord_id,name,address,status,created_at,updated_at) VALUES(?,?,?,?,'ACTIVE',?,?)",id,CurrentUser.require().id(),r.name(),r.address(),LocalDateTime.now(),LocalDateTime.now());return ApiResponse.ok(""+id);}@PostMapping("/units")ApiResponse<String>unit(@RequestBody @Valid Unit r){CurrentUser.requireRole(UserRole.LANDLORD);long owner=CurrentUser.require().id();Integer exists=j.queryForObject("SELECT COUNT(*) FROM property_building WHERE id=? AND landlord_id=?",Integer.class,r.buildingId(),owner);if(exists==null||exists==0)throw new com.renthouse.common.exception.BusinessException("BUILDING_NOT_FOUND","楼盘不存在或无权操作",org.springframework.http.HttpStatus.NOT_FOUND);long id=ids.nextId();j.update("INSERT INTO property_unit(id,building_id,landlord_id,unit_no,title,room_count,hall_count,bathroom_count,area_sqm,occupancy_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'VACANT',?,?)",id,r.buildingId(),owner,r.unitNo(),r.title(),r.rooms(),r.halls(),r.bathrooms(),r.areaSqm(),LocalDateTime.now(),LocalDateTime.now());return ApiResponse.ok(""+id);}public record Building(@NotBlank String name,@NotBlank String address){}public record Unit(@Positive long buildingId,@NotBlank String unitNo,@NotBlank String title,@Min(1)int rooms,@Min(0)int halls,@Min(1)int bathrooms,@Positive double areaSqm){}}
